def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    out = [[0] * w for _ in range(h)]
    if not cells:
        return out

    index = {p: i for i, p in enumerate(cells)}
    tiles = []
    containing = [[] for _ in cells]

    def add_tile(points, color, is_square):
        mask = 0
        for p in points:
            if p not in index:
                return
            mask |= 1 << index[p]
        tid = len(tiles)
        tiles.append((mask, color, is_square))
        for p in points:
            containing[index[p]].append(tid)

    for r in range(h - 1):
        for c in range(w - 1):
            corners = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            add_tile(corners, 1, True)
            # A 3-cell L can be used even when the fourth corner is also
            # occupied; that cell may belong to a neighboring piece.
            for missing, color in enumerate((2, 4, 3, 1)):
                points = [p for i, p in enumerate(corners) if i != missing]
                add_tile(points, color, False)

    full = (1 << len(cells)) - 1

    @lru_cache(None)
    def cover(rem):
        if rem == 0:
            return ()

        best = None
        bits = rem
        while bits:
            bit = bits & -bits
            bits ^= bit
            i = bit.bit_length() - 1
            options = [
                tid for tid in containing[i]
                if tiles[tid][0] & rem == tiles[tid][0]
            ]
            if not options:
                return None
            if best is None or len(options) < len(best):
                best = options
                if len(best) == 1:
                    break

        best.sort(key=lambda tid: (not tiles[tid][2], tiles[tid][1]))
        for tid in best:
            result = cover(rem ^ tiles[tid][0])
            if result is not None:
                return (tid,) + result
        return None

    solution = cover(full)
    if solution is None:
        return out

    for tid in solution:
        mask, color, _ = tiles[tid]
        while mask:
            bit = mask & -mask
            mask ^= bit
            r, c = cells[bit.bit_length() - 1]
            out[r][c] = color
    return out
